using System;using GunmageddonAudio;
public static class C127PolicyTests
{
 static int count;static void Check(bool b,string m){count++;if(!b)throw new Exception(m);}
 public static void Main(){var c=new C127ReloadCycle();Check(c.Ready(0)&&c.Phase(0)==1&&!c.TakeCase(0),"Initially secured, no phantom case");for(int cycle=0;cycle<100;cycle++){double start=cycle*10;c.Begin(start);int handoffs=0;for(int i=0;i<=600;i++){double now=start+i*.01;if(c.TakeCase(now))handoffs++;Check(c.Ready(now)==(now-start>=C127ReloadCycle.Duration),"Readiness requires complete reference reload");Check(c.Phase(now)>=.05&&c.Phase(now)<=1,"Bounded phase");Check(c.Recoil(now)>=-.240001&&c.Recoil(now)<=0,"Bounded recoil");}Check(handoffs==1,"Exactly one casing per shot");}c.Begin(1);Check(c.TakeCase(100)&&!c.TakeCase(100)&&c.Ready(100),"Delayed frame crosses handoff once");c.Reset();Check(c.Ready(0)&&!c.TakeCase(0),"Reset forgets prior shot");Check(!C127Policy.TargetKind(false,true,false)&&C127Policy.TargetKind(false,false,true)&&C127Policy.TargetKind(true,true,false),"Exposed surface only; housed DP");Check(C127Policy.Range(false,12000d*12000)&&!C127Policy.Range(false,12001d*12001)&&!C127Policy.Range(true,6501d*6501)&&!C127Policy.Range(false,199d*199),"Exact envelopes");Check(C127Policy.Score(false,12000,false)>C127Policy.Score(true,200,true),"Every eligible surface contact outranks aircraft");var t=new C127SurfaceTrack();t.Reset();int epoch=t.Epoch;for(int i=0;i<8;i++)t.Observe(new OpticalVector(i*5,0,5000),i*.5,5000,2);Check(t.Ready(3.5)&&!t.Ready(10),"Freshness and acquisition");var a=t.Predict(3.5,2,new OpticalVector());Check(a.X>35,"Observed moving ship is led");t.Correct(epoch-1,100);Check((t.Predict(3.5,2,new OpticalVector())-a).Length==0,"Old-target feedback rejected");t.Correct(epoch,100);Check((t.Predict(3.5,2,new OpticalVector())-a).Length>39,"Observed miss corrects subsequent solution");t.Reset();Check(!t.Ready(3.5)&&t.Epoch!=epoch,"New contact resets knowledge");Console.WriteLine("C127 policy: "+count+" assertions passed");}
}
